<?php
namespace Tests\Feature\Admin;use App\Enums\LeaveStatus;use App\Livewire\Admin\Closures\Index as Closures;use App\Livewire\Admin\Leave\Create;use App\Livewire\Admin\Leave\Index;use App\Livewire\Admin\Leave\Show;use App\Models\Leave;use App\Models\OfficeClosure;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Livewire\Livewire;use Tests\TestCase;
class LeaveWorkspaceTest extends TestCase{use RefreshDatabase;
public function test_employee_submits_and_cancels_own_leave():void{$user=User::factory()->create(['role'=>'sales']);$this->actingAs($user);Livewire::test(Create::class)->set('type','annual')->set('start_date',today()->addWeek()->toDateString())->set('end_date',today()->addWeek()->addDays(2)->toDateString())->set('description','Family holiday')->call('save')->assertHasNoErrors();$leave=Leave::firstOrFail();$this->assertSame($user->id,$leave->user_id);$this->assertSame(LeaveStatus::PENDING,$leave->status);Livewire::test(Index::class)->call('cancel',$leave->id)->assertHasNoErrors();$this->assertSame(LeaveStatus::CANCELLED,$leave->fresh()->status);}
public function test_hr_approves_and_rejects_pending_leave():void{$hr=User::factory()->create(['role'=>'hr']);$one=Leave::factory()->pending()->create(['approved_by'=>null]);$two=Leave::factory()->pending()->create(['approved_by'=>null]);$this->actingAs($hr);Livewire::test(Show::class,['leave'=>$one])->call('approve')->assertHasNoErrors();$this->assertSame(LeaveStatus::APPROVED,$one->fresh()->status);Livewire::test(Show::class,['leave'=>$two])->set('rejection_reason','Insufficient coverage')->call('reject')->assertHasNoErrors();$this->assertSame(LeaveStatus::REJECTED,$two->fresh()->status);$this->assertSame('Insufficient coverage',$two->fresh()->rejection_reason);}
public function test_hr_manages_closures_and_calendar_is_visible_to_employees():void{$hr=User::factory()->create(['role'=>'hr']);$this->actingAs($hr);Livewire::test(Closures::class)->set('title','Company holiday')->set('type','holiday')->set('start_date',today()->toDateString())->set('end_date',today()->toDateString())->call('save')->assertHasNoErrors();$closure=OfficeClosure::firstOrFail();$this->assertSame($hr->id,$closure->created_by);$employee=User::factory()->create(['role'=>'sales']);$this->actingAs($employee)->get(route('admin.leave.calendar'))->assertOk()->assertSee('Company holiday');$this->get(route('admin.closures.index'))->assertForbidden();}
}
